struct HistoryRecorder {
 std::vector<std::pair<std::string,ProfileJson>> records;unsigned attempts=0;bool fail=false;std::function<void()> on_save;
 std::shared_ptr<ProfileHistorySink> sink(){auto out=std::make_shared<ProfileHistorySink>();out->save=[this](const auto& action,const auto& document){++attempts;if(on_save)on_save();if(fail)throw std::runtime_error("injected disk failure");records.push_back({action,document});};return out;}
};
